        })
      }
    }
    const c = per.get(ev.key) ?? { a: 0, d: 0 }
    if (denied === null) { c.a++; ta++ } else { c.d++; td++ }
    per.set(ev.key, c)
    if (mode === 'replay') out.push(`${ev.tickText} ${ev.key} ${denied === null ? 'allow' : 'deny ' + denied}`)
  }
  if (mode === 'summary') {
    for (const k of [...per.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
      out.push(`${k} allowed=${per.get(k).a} denied=${per.get(k).d}`)
    }
    out.push(`total allowed=${ta} denied=${td}`)
  }
  return out.length ? out.join('\n') + '\n' : ''
}

